<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($title)?></title><link rel="icon" href="/assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.min.css"><script defer src="/assets/app.min.js"></script></head>
<body class="<?=e($theme)?>"><header><a class="brand" href="/"><img src="/assets/mark.svg" width="32" height="32" alt=""><?=e($title)?></a><nav aria-label="Главная навигация"><a href="/">Мероприятия</a><?php if (!empty($user)): ?><a href="/?page=account">Кабинет</a><a href="/?page=<?= $user['role']==='admin' ? 'admin' : 'applications' ?>"><?= $user['role']==='admin' ? 'Все заявки' : 'Мои заявки' ?></a><form method="post"><?=csrf()?><button class="link" name="action" value="logout">Выйти</button></form><?php else: ?><a href="/?page=login">Войти</a><a class="button small" href="/?page=register">Регистрация</a><?php endif; ?></nav></header>
<main><?php if ($error): ?><p class="alert error" role="alert"><?=e($error)?></p><?php endif; ?><?php if ($notice): ?><p class="alert" role="status"><?=e($notice)?></p><?php endif; ?>
<?php if ($page==='events'): ?>
<section class="hero"><p class="eyebrow"><?= $theme==='workshop' ? 'ТВОРЧЕСТВО И ПРАКТИКА' : 'ЗНАНИЯ • ОБЩЕНИЕ • РАЗВИТИЕ' ?></p><h1><?= $theme==='workshop' ? 'Создавайте своими руками' : 'Встречаемся, чтобы узнать больше' ?></h1><p><?= $theme==='workshop' ? 'Мастер-классы для тех, кто хочет попробовать новое.' : 'Конференции о технологиях, дизайне и образовании. Выберите встречу и подайте заявку на участие.' ?></p><a class="button" href="#events">Выбрать мероприятие ↓</a><img class="hero-art" src="/assets/<?= $theme==='workshop' ? 'workshop' : 'conference' ?>.svg" width="190" height="150" alt=""></section>
<div class="section-title" id="events"><h2>Ближайшие встречи</h2><span>Программа сезона</span></div><div class="grid">
<?php foreach ($events as $event): $past=strtotime($event['event_date'])<=time(); ?><article class="card"><p class="eyebrow"><?=e(date('d.m.Y · H:i',strtotime($event['event_date'])))?></p><h3><?=e($event['title'])?></h3><p class="muted"><?=e($event['location'])?></p><p><?=e($event['description'])?></p><div class="card-bottom"><?php if ($past): ?><span class="badge">Мероприятие завершено</span><?php elseif (($user['role'] ?? '')!=='admin'): ?><a class="button secondary" href="/?page=apply&amp;event=<?=$event['id']?>">Подать заявку</a><?php else: ?><span class="badge">Приём заявок открыт</span><?php endif; ?></div></article><?php endforeach; ?></div>
<?php elseif ($page==='register' || $page==='login'): $register=$page==='register'; ?>
<section class="form-panel"><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</p><h1><?=$register ? 'Регистрация' : 'Вход'?></h1><p class="muted"><?=$register ? 'Создайте аккаунт для участия в мероприятиях.' : 'Введите логин и пароль.'?></p><form method="post" data-validate><?=csrf()?><input type="hidden" name="action" value="<?=$page?>"><label>Логин<input name="login" autocomplete="username" required minlength="3" maxlength="40" pattern="[a-zA-Z0-9_]{3,40}" value="<?=e($_POST['login'] ?? '')?>"><small>Латинские буквы, цифры, подчёркивание</small></label><?php if ($register): ?><label>Электронная почта<input name="email" type="email" required maxlength="254" autocomplete="email" value="<?=e($_POST['email'] ?? '')?>"></label><label>Телефон<input name="phone" type="tel" required pattern="\+7[0-9]{10}" placeholder="+79991234567" autocomplete="tel" value="<?=e($_POST['phone'] ?? '')?>"></label><?php endif; ?><label>Пароль<input name="password" type="password" required <?=$register ? 'minlength="8" maxlength="72"' : ''?> autocomplete="<?=$register ? 'new-password' : 'current-password'?>"><?php if ($register): ?><small>Не менее 8 символов</small><?php endif; ?></label><p class="client-error" role="alert"></p><button><?=$register ? 'Зарегистрироваться' : 'Войти'?></button></form><p><a href="/?page=<?=$register ? 'login' : 'register'?>"><?=$register ? 'Уже есть аккаунт? Войти' : 'Создать аккаунт'?></a></p></section>
<?php elseif ($page==='account'): ?><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</p><h1>Здравствуйте, <?=e($user['login'])?>!</h1><section class="card account"><h2>Мой профиль</h2><dl><dt>Почта</dt><dd><?=e($user['email'])?></dd><dt>Телефон</dt><dd><?=e($user['phone'])?></dd><dt>Роль</dt><dd><?=$user['role']==='admin' ? 'Администратор' : 'Участник'?></dd></dl><a class="button" href="/?page=<?=$user['role']==='admin' ? 'admin' : 'applications'?>">Перейти к заявкам</a></section>
<?php elseif ($page==='apply'): ?><section class="form-panel"><h1>Новая заявка</h1><form method="post" data-validate><?=csrf()?><input type="hidden" name="action" value="apply"><label>Мероприятие<select name="event" required><option value="">Выберите мероприятие</option><?php foreach ($events as $event): if (strtotime($event['event_date'])<=time()) continue; ?><option value="<?=$event['id']?>" <?= (string)$event['id']===(string)($_POST['event'] ?? $_GET['event'] ?? '') ? 'selected' : '' ?>><?=e($event['title'])?></option><?php endforeach; ?></select></label><label>Способ оплаты<select name="payment" required><option value="card">Банковская карта</option><option value="invoice">По счёту</option></select></label><label>Помещение<select name="room" required><option value="main">Большой зал</option><option value="small">Малый зал</option><option value="online">Онлайн</option></select></label><p class="muted">Выбор способа оплаты сохраняется в заявке. Онлайн-оплата на портале не проводится.</p><p class="client-error" role="alert"></p><button>Отправить заявку</button></form></section>
<?php elseif ($page==='applications' || $page==='admin'): $admin=$page==='admin'; $filter=(int)($_GET['status'] ?? 0); $apps=$portal->applications($user,$filter); ?>
<p class="eyebrow"><?=$admin ? 'АДМИНИСТРИРОВАНИЕ' : 'ЛИЧНЫЙ КАБИНЕТ'?></p><h1><?=$admin ? 'Все заявки' : 'Мои заявки'?></h1><?php if ($admin): ?><form method="get" class="filter"><input type="hidden" name="page" value="admin"><label>Статус<select name="status"><option value="0">Все статусы</option><?php foreach ([1=>'Новая',2=>'Назначено',3=>'Завершено'] as $id=>$name): ?><option value="<?=$id?>" <?=$filter===$id ? 'selected' : ''?>><?=$name?></option><?php endforeach; ?></select></label><button>Показать</button></form><?php else: ?><p><a href="/?page=apply">+ Новая заявка</a></p><?php endif; ?>
<div class="grid"><?php foreach ($apps as $app): ?><article class="card"><div class="section-title"><span class="muted">Заявка №<?=$app['id']?></span><span class="badge status-<?=$app['status_id']?>"><?=e($app['status_name'])?></span></div><h2><?=e($app['title'])?></h2><p><?=e(date('d.m.Y · H:i',strtotime($app['event_date'])))?> · <?=e($app['location'])?></p><p class="muted"><?=e(['card'=>'Карта','invoice'=>'По счёту'][$app['payment']])?> · <?=e(['main'=>'Большой зал','small'=>'Малый зал','online'=>'Онлайн'][$app['room']])?></p><p class="muted">Создана: <?=e($app['created_at'])?></p><?php if ($admin): ?><p>Участник: <?=e($app['login'])?></p><?php if ($app['status_id']<3): ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$app['id']?>"><input type="hidden" name="status" value="<?=$app['status_id']+1?>"><button class="secondary"><?=$app['status_id']==1 ? 'Назначить' : 'Завершить'?></button></form><?php endif; ?><?php elseif ($app['status_id']==1): ?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$app['id']?>"><button name="action" value="cancel" class="secondary">Удалить заявку</button></form><?php endif; ?>
<?php if ($app['body']!==null): ?><div class="review"><strong>Отзыв · <?=$app['rating']?>/5</strong><p><?=e($app['body'])?></p></div><?php elseif (!$admin && $app['status_id']==3 && strtotime($app['event_date'])<=time()): ?><form method="post" data-validate class="review"><?=csrf()?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?=$app['id']?>"><label>Оценка<select name="rating"><?php for ($i=5;$i>=1;$i--): ?><option value="<?=$i?>"><?=$i?></option><?php endfor; ?></select></label><label>Отзыв<textarea name="body" required minlength="5" maxlength="1000" rows="3"></textarea></label><p class="client-error" role="alert"></p><button>Оставить отзыв</button></form><?php elseif (!$admin): ?><p class="muted">Отзыв откроется после мероприятия и завершения заявки.</p><?php endif; ?></article><?php endforeach; ?></div><?php if (!$apps): ?><div class="empty">Заявок пока нет.</div><?php endif; ?>
<?php else: ?><h1>Страница недоступна</h1><a href="/">На главную</a><?php endif; ?>
</main><footer><strong><?=e($title)?></strong><span>Учебный портал · 2026</span></footer></body></html>
